INSERT INTO resy_experiences (id, name, short_description, long_description, image_url, is_external, external_url, reservation_type, price, show_price, display_order, is_active, location_id, show_waitlist, points_earned, created_at, updated_at) VALUES ('9259bec6-b134-4b04-a5c2-f60c2c367956', 'Wine Tasting at the Winery Tasting Bar', 'Formal Tasting Room In our seated indoor tasting room, one of our Estate Hosts will guide you through an unforgettable experience. ', 'Formal Tasting Room In our seated indoor tasting room, one of our Estate Hosts will guide you through an unforgettable experience. Tastings: $16 per person Includes 8 tokens and a commemorative Nashoba wine glass Tokens may be used for any of our products crafted on-site Wine, Beer & Hard Cider: 1 token each Distilled Spirits: 2 tokens each This experience lasts approximately 45 minutes, giving you time to mix and match your selections at your own pace. To complement your tasting, cheese boards are available for purchase. Reservations: Strongly recommended on weekends Held for a maximum of 10 minutes before being forfeited Non-refundable and cannot be rescheduled Goal of the Experience: Our Formal Tasting Room is designed for guests who want to learn about our wines and operations while sampling. Unlike the Pavilion Tasting area, which emphasizes casual conversation, this guided session focuses on education and exploration. Please manage your time to complete your tasting wi', '/api/media-library/4b0e8a49-33bd-4fb3-8fdb-40891e3dcb1e/file', false, 'https://tables.toasttab.com/restaurants/f6a9a99b-0a3a-4a5b-904f-c8c82a46d793/reserve?partySize=2&dateTime=2025-12-17T11:00:00.000-05:00', 'ticketed', '16.00', false, 0, true, '66fd6924-1bfb-426b-955d-168be80ddd63', false, 0, '2025-11-20T12:10:42.875Z', '2025-12-06T14:42:20.794Z');
INSERT INTO resy_experiences (id, name, short_description, long_description, image_url, primary_image_key, is_external, external_url, show_price, display_order, is_active, location, show_waitlist, points_earned, created_at, updated_at) VALUES ('0f28e907-08d0-439c-b384-949c7612f532', 'J''s Restaurant', 'Award-winning farm-to-table dining experience in our elegant restaurant.', 'J''s Restaurant offers an exceptional farm-to-table dining experience featuring seasonal ingredients from our orchards and local farms. Our chef-crafted menu showcases the best of New England cuisine paired with our award-winning wines. Reservations managed through OpenTable.', '/api/media-library/c693f47b-a12d-4d61-8026-321cb86f42d3/file', '/objects/uploads/fbd16716-8b38-4c92-908d-e573d0e00cf8', true, 'https://www.opentable.com/booking/restref/availability?rid=231097&lang=en-US&color=1&r3uid=cfe&dark=false&correlationId=f0b562f6-da9c-4c60-b6ef-71a7c3bdcbce&restRef=231097&partySize=4&dateTime=2025-05-17T19%3A00&otSource=Restaurant%20website', true, 1, true, 'Bolton, MA', false, 0, '2025-11-18T18:31:43.954Z', '2025-12-06T03:06:55.685Z');
INSERT INTO resy_experiences (id, name, short_description, long_description, image_url, primary_image_key, is_external, external_url, reservation_type, show_price, display_order, is_active, location_id, show_waitlist, points_earned, created_at, updated_at) VALUES ('d9f6ddbe-3814-41e7-8fc0-cbe046d13ab9', 'Mother''s Day 2026', 'Test for Mother''s Day', 'Test for Mother''s Day', '', '/objects/uploads/f4daff7b-b4e8-4a4e-8acf-43189d7274cd', false, '', 'table', true, 0, false, '7aa3de06-e490-4e17-be61-bb7420fb7d52', false, 0, '2025-11-20T11:09:04.383Z', '2025-12-06T03:07:14.144Z');
INSERT INTO resy_experiences (id, name, description, short_description, long_description, image_url, primary_image_key, is_external, external_url, reservation_type, show_price, display_order, is_active, show_waitlist, points_earned, created_at, updated_at) VALUES ('7b3dcc5f-3b47-4e6b-8244-4987293b8097', 'Pavilion Tastings', 'Outdoor tasting experience at our scenic pavilion overlooking the vineyard.', 'Pavilion Tasting', '', '/@fs/home/runner/workspace/attached_assets/generated_images/Outdoor_pavilion_tasting_5f38a008.png', '/objects/uploads/afaea93d-a9b9-46ba-8e5f-7050128e0a33', false, '', 'table', true, 4, false, false, 0, '2025-11-18T18:06:50.929Z', '2025-12-06T14:50:33.540Z');
INSERT INTO resy_experiences (id, name, description, short_description, long_description, image_url, primary_image_key, is_external, external_url, reservation_type, show_price, display_order, is_active, show_waitlist, points_earned, created_at, updated_at) VALUES ('fd589420-3c4f-4c93-b1e8-069c66db7516', 'The Knoll Restaurant', 'Casual dining with spectacular views and locally-sourced ingredients.', '', '', '/@fs/home/runner/workspace/attached_assets/generated_images/Knoll_outdoor_dining_vista_a227d3e7.png', '/objects/uploads/ae524e27-6107-4fec-9a06-65f44d10cb97', false, '', 'table', true, 5, false, false, 0, '2025-11-18T18:06:50.929Z', '2025-12-06T14:50:44.066Z');
INSERT INTO resy_experiences (id, name, description, short_description, long_description, image_url, is_external, external_url, reservation_type, price, show_price, display_order, is_active, location_id, show_waitlist, points_earned, created_at, updated_at) VALUES ('dfec79db-db48-475d-8779-d6179ba37f57', 'Winery Tours', 'Behind-the-scenes tour of our winery, distillery and brewery with tastings included.', '', '', '/api/media-library/6270bf85-6a5b-47a7-96d5-59adb87a0d15/file', false, '', 'ticketed', '16.00', true, 3, true, '08b02d64-21f2-4df8-941d-af98dc51fc08', false, 0, '2025-11-18T18:06:50.929Z', '2025-12-06T14:59:39.117Z');
INSERT INTO resy_experiences (id, name, description, short_description, long_description, image_url, primary_image_key, is_external, external_url, reservation_type, show_price, display_order, is_active, location_id, show_waitlist, closed_message, fully_booked_message, private_event_message, points_earned, created_at, updated_at) VALUES ('693ed83c-e010-496b-8cfd-f145c86da742', 'Pavilion Seating', 'Reserve a table at our outdoor pavilion for wine, beer, and light fare.', '', 'You are making a reservation for a Table at The Knoll which is an Outdoor Restaurant without any Indoor seating. Reservations are available up to 30 days in advance and close at 7:00 AM each day for same-day bookings. After 7:00 AM, reservations for that day can no longer be made. We welcome walk-ins throughout the day, as we are almost never fully booked. There may be a short wait during busy times. Group Sizes Maximum reservation size: 14 guests (adults, children, and babies included) Groups larger than 14 must be booked as a private event. We do not combine tables, reserve specific tables, or seat multiple reservations together. Outdoor seating is first come, first served — reservations are not available during the off-season. All outdoor tables have umbrellas. Accessibility & Food Policy If you need an accessible table, please make a reservation and then email support@nashobawinery.com with your name, date, and time — we’ll ensure you are seated appropriately. ', '/@fs/home/runner/workspace/attached_assets/generated_images/Pavilion_event_seating_6daeb5b9.png', '/objects/uploads/0fd4e3ea-ed66-4f7d-b3a2-75f6b95508d6', false, '', 'table', true, 1, false, 'a82604d4-0f32-43b4-ad04-28e2bf92456c', false, 'We are currently closed. Please check back during our operating hours.', 'All reservations are fully booked for this date. Please try another date or join our waitlist.', 'This location is reserved for a private event. We apologize for the inconvenience.', 0, '2025-11-18T18:06:50.929Z', '2025-12-06T14:50:02.672Z');
